<script setup>import { computed, ref } from 'vue'; import { Check, Save, Search } from 'lucide-vue-next'; import { students } from '../data/demo'; const list=ref(students.map(x=>({...x}))); const saved=ref(false); const count=computed(()=>list.value.filter(x=>x.status==='Có mặt').length); const set=(s,status)=>s.status=status; const save=()=>{saved.value=true; setTimeout(()=>saved.value=false,2500)};</script>
<template><div><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-sm text-primary-600">Chủ nhật, 24 tháng 8 · 08:00</p><h2 class="text-xl font-bold text-ink">Điểm danh — Ấu Nhi 1A</h2><p class="mt-1 text-sm text-slate-500">{{count}}/{{list.length}} em có mặt · Phòng A1</p></div><button @click="save" class="inline-flex items-center gap-2 rounded-xl bg-primary-600 px-4 py-2.5 text-sm font-semibold text-white"><Save class="size-4"/>Lưu điểm danh</button></div><div v-if="saved" role="status" class="mt-5 flex items-center gap-2 rounded-xl bg-emerald-50 p-3 text-sm text-emerald-700"><Check class="size-4"/>Đã lưu điểm danh thành công.</div><div class="mt-6 overflow-hidden rounded-2xl border border-slate-200 bg-white"><div class="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 p-4"><label class="flex items-center gap-2 rounded-xl bg-slate-50 px-3 py-2 text-slate-400"><Search class="size-4"/><input class="bg-transparent text-sm outline-none" placeholder="Tìm thiếu nhi..."/></label><button @click="list.forEach(s=>set(s,'Có mặt'))" class="text-sm font-medium text-primary-600">Đánh dấu tất cả có mặt</button></div><div class="divide-y divide-slate-100"><article v-for="student in list" :key="student.id" class="flex flex-wrap items-center gap-3 p-4"><span class="grid size-10 place-items-center rounded-full bg-primary-100 text-sm font-semibold text-primary-700">{{student.initials}}</span><div class="min-w-40 flex-1"><p class="font-medium text-ink">{{student.name}}</p><p class="text-xs text-slate-500">{{student.saint}}</p></div><div class="flex rounded-lg bg-slate-100 p-1 text-xs"><button v-for="status in ['Có mặt','Đi trễ','Nghỉ có phép']" @click="set(student,status)" :class="student.status===status?'bg-white text-primary-700 shadow-sm':'text-slate-500'" class="rounded-md px-2.5 py-1.5">{{status}}</button></div></article></div></div></div></template>
